#include <vector>

using namespace std;

class Solution {
public:
    int maximumPossibleSize(vector<int>& nums) {
        int ans = 0;
        int prev = 0;
        for (int num : nums) {
            if (num >= prev) {
                prev = num;
                ans++;
            }
        }
        return ans;
    }
};

